<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
if (($_SESSION['role'] ?? '') !== 'headteacher') { http_response_code(403); exit('Only the Head of School can manage classes, streams and subjects.'); }
$uid=(int)$_SESSION['user_id'];$db=db();$error='';$saved=isset($_GET['saved']);
$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');$schoolId=(int)($_POST['school_id']??0);$name=trim((string)($_POST['name']??''));
    if(!in_array($schoolId,$schoolIds,true)){$error='Choose a school assigned to your account.';}
    elseif(!in_array($action,['class','subject','stream'],true)){$error='Choose a valid academic setup action.';}
    elseif($name===''||strlen($name)>($action==='subject'?100:80)){$error='Enter a name within the allowed length.';}
    else{
        try{
            $db->beginTransaction();
            if($action==='class'){$q=$db->prepare('INSERT INTO school_classes(school_id,name,created_by) VALUES(?,?,?)');$q->execute([$schoolId,$name,$uid]);$entity='school_class';$id=(int)$db->lastInsertId();}
            elseif($action==='subject'){$q=$db->prepare('INSERT INTO school_subjects(school_id,name,created_by) VALUES(?,?,?)');$q->execute([$schoolId,$name,$uid]);$entity='school_subject';$id=(int)$db->lastInsertId();}
            else{$classId=(int)($_POST['class_id']??0);$q=$db->prepare('SELECT c.id FROM school_classes c JOIN school_memberships m ON m.school_id=c.school_id WHERE c.id=? AND c.school_id=? AND m.user_id=?');$q->execute([$classId,$schoolId,$uid]);if(!$q->fetch())throw new DomainException('Choose a class in the selected school.');$q=$db->prepare('INSERT INTO school_streams(class_id,name,created_by) VALUES(?,?,?)');$q->execute([$classId,$name,$uid]);$entity='school_stream';$id=(int)$db->lastInsertId();}
            $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'create',$entity,$id,json_encode(['school_id'=>$schoolId,'name'=>$name],JSON_THROW_ON_ERROR)]);$db->commit();header('Location: school_setup.php?saved=1');exit;
        }catch(DomainException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getMessage();}catch(PDOException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getCode()==='23000'?'That name already exists in this school or class.':'Academic setup could not be saved. Apply the latest database migration.';}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error='Academic setup could not be saved. Apply the latest database migration.';}
    }
}
$classes=[];$subjects=[];$streams=[];$loadError='';
try{if($schoolIds){$marks=implode(',',array_fill(0,count($schoolIds),'?'));$q=$db->prepare("SELECT c.id,c.school_id,c.name,s.name school_name,(SELECT COUNT(*) FROM school_streams st WHERE st.class_id=c.id) stream_count FROM school_classes c JOIN schools s ON s.id=c.school_id WHERE c.school_id IN ($marks) ORDER BY s.name,c.name");$q->execute($schoolIds);$classes=$q->fetchAll();$q=$db->prepare("SELECT sj.id,sj.school_id,sj.name,s.name school_name FROM school_subjects sj JOIN schools s ON s.id=sj.school_id WHERE sj.school_id IN ($marks) ORDER BY s.name,sj.name");$q->execute($schoolIds);$subjects=$q->fetchAll();$q=$db->prepare("SELECT st.id,st.name,c.name class_name,c.school_id,s.name school_name FROM school_streams st JOIN school_classes c ON c.id=st.class_id JOIN schools s ON s.id=c.school_id WHERE c.school_id IN ($marks) ORDER BY s.name,c.name,st.name");$q->execute($schoolIds);$streams=$q->fetchAll();}}catch(Throwable $ex){$loadError='Academic setup could not be loaded. Apply the latest database migration.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School setup · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="academics.php">▤ &nbsp;Academics</a><a class="nav-item active" href="school_setup.php" aria-current="page">⚙ &nbsp;School setup</a><a class="nav-item" href="notes.php">▧ &nbsp;Learning notes</a></nav><div class="sidebar-bottom"><a class="nav-item" href="profile.php">◉ &nbsp;My account</a><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Academics <span>/</span> School setup</div><div class="top-actions"><span class="role-chip">Head of school</span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h1>School setup</h1><p class="muted">Set up your classes, class streams and subjects before assigning teachers.</p></div><a class="button" href="academics.php">Back to Academics</a></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($saved):?><div class="notice success" role="status">Academic setup saved.</div><?php endif;?><?php if($loadError):?><div class="notice error" role="alert"><?=e($loadError)?></div><?php endif;?>
<?php if(!$schools):?><div class="empty-state"><h3>No school is assigned yet</h3><p>Ask your director to link your Head of School account to a school first.</p></div><?php else:?>
<div class="setup-card-grid">
<section class="note-create setup-card"><div class="setup-card-icon" aria-hidden="true">▦</div><div class="eyebrow">CLASS LEVELS</div><h2>Add a class</h2><p class="muted">Create a class level, such as Grade 4 or Form 1.</p><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="class"><div class="form-grid"><?=render_school_select('class-school',$schools)?><div><label for="class-name">Class name</label><input id="class-name" name="name" maxlength="80" required value="<?=e($_POST['action']??'')==='class'?e($_POST['name']??''):''?>" placeholder="For example, Grade 4"></div></div><button class="button primary" type="submit">Add class</button></form></section>
<section class="note-create setup-card"><div class="setup-card-icon subject" aria-hidden="true">▤</div><div class="eyebrow">CURRICULUM</div><h2>Add a subject</h2><p class="muted">Add a subject available for teaching and assessment.</p><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="subject"><div class="form-grid"><?=render_school_select('subject-school',$schools)?><div><label for="subject-name">Subject name</label><input id="subject-name" name="name" maxlength="100" required value="<?=e($_POST['action']??'')==='subject'?e($_POST['name']??''):''?>" placeholder="For example, Mathematics"></div></div><button class="button primary" type="submit">Add subject</button></form></section>
<section class="note-create setup-card"><div class="setup-card-icon stream" aria-hidden="true">↔</div><div class="eyebrow">CLASS GROUPS</div><h2>Add a stream</h2><p class="muted">Add a stream within one of your school’s classes.</p><form method="post" class="note-form" data-stream-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="stream"><div class="form-grid"><?=render_school_select('stream-school',$schools)?><div><label for="stream-class">Class</label><select id="stream-class" name="class_id" required <?=!$classes?'disabled':''?>><option value=""><?= $classes?'Choose class':'Add a class before creating streams' ?></option><?php foreach($classes as $class):?><option value="<?=$class['id']?>" data-school-id="<?=$class['school_id']?>"><?=e($class['name'].' · '.$class['school_name'])?></option><?php endforeach;?></select></div><div><label for="stream-name">Stream name</label><input id="stream-name" name="name" maxlength="80" required value="<?=e($_POST['action']??'')==='stream'?e($_POST['name']??''):''?>" placeholder="For example, Blue"></div></div><button class="button primary" type="submit" <?=!$classes?'disabled':''?>>Add stream</button></form></section>
</div>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHOOL STRUCTURE</div><h2>Classes and streams</h2></div><span class="count-pill"><?=count($classes)?> classes · <?=count($streams)?> streams</span></div><?php if(!$classes):?><div class="empty-state"><h3>No classes added yet</h3><p>Add your first class above, then you can add streams to it.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Class</th><th>Streams</th></tr></thead><tbody><?php foreach($classes as $class):?><tr><td><?=e($class['school_name'])?></td><td><?=e($class['name'])?></td><td><?=number_format((int)$class['stream_count'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">SUBJECT CATALOGUE</div><h2>Subjects</h2></div><span class="count-pill"><?=count($subjects)?> subjects</span></div><?php if(!$subjects):?><div class="empty-state"><h3>No subjects added yet</h3><p>Add subjects used in this school’s classes.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Subject</th></tr></thead><tbody><?php foreach($subjects as $subject):?><tr><td><?=e($subject['school_name'])?></td><td><?=e($subject['name'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="content-section"><div class="section-heading"><div><div class="eyebrow">CLASS GROUPS</div><h2>Streams</h2></div><span class="count-pill"><?=count($streams)?> streams</span></div><?php if(!$streams):?><div class="empty-state"><h3>No streams added yet</h3><p>Streams appear here when added to a class.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Class</th><th>Stream</th></tr></thead><tbody><?php foreach($streams as $stream):?><tr><td><?=e($stream['school_name'])?></td><td><?=e($stream['class_name'])?></td><td><?=e($stream['name'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php endif;?></div></main></div><script>document.querySelectorAll('[data-stream-form]').forEach(form=>{const school=form.querySelector('[name="school_id"]'),classes=form.querySelector('#stream-class');const filter=()=>{const schoolId=school?.value||'';[...classes.options].forEach(option=>{if(!option.value)return;const visible=!schoolId||option.dataset.schoolId===schoolId;option.hidden=!visible;option.disabled=!visible;if(!visible&&option.selected)classes.value=''})};school?.addEventListener('change',filter);filter()});</script></body></html>
